Method.Source:
/// <summary>
/// Job zum setzen der Verknüpfung von BV und Aktivität 
/// zusätzlich zum Record in smmActivityParentLinkTable ist ein Record in KCS_KBVBuildingProjectTable notwendig - dieser wird erstellt für Daten aus Vergangenheit
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    smmActivityParentLinkTable  parentLinkTable;
    KCS_KBVBuildingProjectTable buildingProjectTable;

    while select parentLinkTable where parentLinkTable.ParentType == smmActivityParentType::BuildingProject
    {
        buildingProjectTable = KCS_KBVBuildingProjectTable::findByRecId(parentLinkTable.RefRecId);
        if (buildingProjectTable.KCS_KBVBuildingProjectID)
        {
            if (!KCS_KBVActivitiesForBP::exist(buildingProjectTable.KCS_KBVBuildingProjectID, parentLinkTable.ActivityNumber))
            {
                KCS_KBVActivitiesForBP::createReference(buildingProjectTable.KCS_KBVBuildingProjectID, parentLinkTable.ActivityNumber, curExt());
            }
        }
    }
}
